mapper.select:
select i.id, i.task_num, i.time_point, i.org_code, i.task_type, i.deadline, i.gmt_update,
a.audit_status, a.biz_type, a.latest_msg, a.id as audit_task_id, a.current_operator, a.pre_operator, a.gmt_create, a.gmt_update
from (select * from audit_task where biz_type = 'BLACK_GRAY_WAREHOUSE_TASK') a inner join black_gray_warehouse_task i on i.id = a.biz_id

    
        and a.current_operator like concat('%',#{param.currentOperator},'%')
    
    
        and i.id = #{param.id}
    
    
        and i.task_num like concat('%',#{param.taskNum},'%')
    
    
        and i.time_point = #{param.timePoint}
    
    
        and i.audit_status = #{param.auditStatus}
    
    
        and i.org_Code = #{param.orgCode}
    
    
        and i.business_source = #{param.businessSource}
    

order by i.gmt_update desc, i.id desc
